    private final PackOutput packOutput;
    public ExOreAdvancementGenerator(PackOutput output)
    {
        packOutput = output;
    }
    @Override
    public CompletableFuture<?> run(CachedOutput cachedOutput)
    {
        Path path = packOutput.getOutputFolder();
        Set<ResourceLocation> set = Sets.newHashSet();
        var futures = new ArrayList<CompletableFuture<?>>();
        Consumer<Advancement> consumer = (advancement) ->
        {
            if(!set.add(advancement.getId()))
            {
                throw new IllegalStateException("Duplicate Advancement" + advancement.getId());
            }
            else
            {
                Path path1 = createPath(path,advancement);
                futures.add(DataProvider.saveStable(cachedOutput,advancement.deconstruct().serializeToJson(),path1));
            }
        };
        generateAdvancements(consumer);
        return CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new));
    }
